// Public-site i18n: fa is the primary language, en is secondary.
// Stores the choice under `siteLang`, mirrors admin panel behavior (`adminLang`).
import { createContext, useContext } from 'react';

export const DEFAULT_LANG = 'fa';

export const SiteLangContext = createContext({
  lang: DEFAULT_LANG,
  setLang: () => {},
  t: () => '',
});

export const useSiteLang = () => useContext(SiteLangContext);

// Access a bilingual data field: { fa: '...', en: '...' } or plain string.
export const L = (value, lang) => {
  if (value == null) return '';
  if (typeof value === 'string') return value;
  return value[lang] ?? value.fa ?? value.en ?? '';
};

